import csv

with open('csv/qualifying.csv', 'r') as f:
    reader = csv.DictReader(f)
    race_903_rows = []
    for row in reader:
        if row['raceId'] == '903':
            q3 = row['q3']
            if q3:  # Skip empty Q3
                race_903_rows.append((row['number'], q3))

    def parse_time(t):
        parts = t.split(':')
        if len(parts) == 2:
            mins, secs = parts
            return float(mins) * 60 + float(secs)
        return float(t)

    target_seconds = 114  # 1:54 = 60 + 54 = 114 seconds
    closest = min(race_903_rows, key=lambda x: abs(parse_time(x[1]) - target_seconds))
    print(f"Closest to 1:54: Number {closest[0]}, Q3: {closest[1]}")
    print(f"\nAll Q3 times for race 903:")
    for num, q3 in sorted(race_903_rows, key=lambda x: parse_time(x[1])):
        print(f"  Number {num}: {q3}")

